-- Step 1
UPDATE export_orders
SET produced_qty = COALESCE(produced_qty, 0) + 9
WHERE order_no = '1471';

-- Step 2
INSERT INTO order_logs (order_no, log_date, activity_type, qty)
VALUES ('1471', '2026-04-08'::date, 'Produced', 9);

-- Step 3
DELETE FROM work_orders
WHERE order_no = '1471';

-- Step 4
DELETE FROM production_logs
WHERE order_no = '1471';
